python -c "
import sys, os, re, glob
sys.stdout.reconfigure(encoding='utf-8')
base = 'C:/Users/joaqu/Documents/5to-semestre/SistemasDistribuidos'
files = sorted(glob.glob(os.path.join(base, 'Unidad*.md')))
for f in files:
    content = open(f, encoding='utf-8').read()
    lines = content.split('\n')
    issues = []
    for i, line in enumerate(lines):
        if line.lstrip().startswith('|'):
            if i == 0 or (not lines[i-1].strip() and not lines[i-1].startswith(('|','|'))):
                pass
            elif lines[i-1].strip() == '' or lines[i-1].strip().startswith('|'):
                pass
            else:
                if not lines[i-1].strip().endswith('|') and not lines[i-1].strip() == '':
                    pass
    # simpler: count tables whose immediate previous non-boundary is not blank
    for i, line in enumerate(lines):
        if line.lstrip().startswith('|') and i > 0 and lines[i-1].strip() != '' and not lines[i-1].lstrip().startswith('|'):
            issues.append(i+1)
    print(os.path.basename(f), '| tables w/o blank line before:', issues if issues else 'ok')
"

